using System.Collections.Generic;
using System.Text;
using Hearth.Tests.Generated;
using Newtonsoft.Json.Linq;
using NUnit.Framework;

namespace Hearth.Tests
{
    /// <summary>
    /// The typed mirror over code generated by <c>hearth-mp codegen --unity</c> from
    /// <c>examples/tictactoe</c> and <c>examples/arena</c> (see <c>Generated/</c>).
    /// </summary>
    public class TypedRuntimeTests
    {
        static JToken J(string json) => JToken.Parse(json);

        /// <summary>Apply ops to a state copy, as the core does, then hand both to the room.</summary>
        static JToken Patch<T>(HearthRoom<T> room, JToken state, string ops) where T : HearthNode, new()
        {
            var next = state.DeepClone();
            var array = JArray.Parse(ops);
            foreach (JObject op in array)
                ApplyOp(next, op);
            room.ApplyPatch(next, array);
            return next;
        }

        static void ApplyOp(JToken state, JObject op)
        {
            var path = (JArray)op["path"];
            JToken node = state;
            var kind = (string)op["op"];
            var depth = kind == "set" || kind == "del" ? path.Count - 1 : path.Count;
            for (var i = 0; i < depth; i++)
                node = node[path[i].Type == JTokenType.Integer ? (object)(int)path[i] : (string)path[i]];
            var last = path.Count > 0 ? path[path.Count - 1] : null;
            switch (kind)
            {
                case "set":
                    if (last.Type == JTokenType.Integer) node[(int)last] = op["value"];
                    else node[(string)last] = op["value"];
                    break;
                case "del":
                    ((JObject)node).Remove((string)last);
                    break;
                case "map_insert":
                    node[(string)op["key"]] = op["value"];
                    break;
                case "list_splice":
                    var list = (JArray)node;
                    for (var d = 0; d < (int)op["delete"]; d++) list.RemoveAt((int)op["index"]);
                    var at = (int)op["index"];
                    foreach (var item in (JArray)op["insert"]) list.Insert(at++, item);
                    break;
            }
        }

        const string Arena = "{\"avatars\":{\"p1\":{\"pos\":[1.0,2.0]}},\"coins\":[[5.0,5.0]]}";

        [Test]
        public void MapInsert_RaisesOneOnAdd()
        {
            var room = new HearthRoom<ArenaRoomArena>();
            room.ApplyReset(J(Arena));
            var added = new List<string>();
            room.State.Avatars.OnAdd += (key, value) => added.Add(key + ":" + value.Pos[0]);
            Patch(room, J(Arena), "[{\"op\":\"map_insert\",\"path\":[\"avatars\"],\"key\":\"p2\",\"value\":{\"pos\":[3.0,4.0]}}]");
            CollectionAssert.AreEqual(new[] { "p2:3" }, added);
            Assert.AreEqual(2, room.State.Avatars.Count);
        }

        [Test]
        public void NestedSet_FieldEventOnSameInstance_PlusMapOnChange()
        {
            var room = new HearthRoom<ArenaRoomArena>();
            room.ApplyReset(J(Arena));
            var held = room.State.Avatars["p1"];
            var posChanges = 0;
            var mapChanges = new List<string>();
            held.Pos.OnChange += () => posChanges++;
            room.State.Avatars.OnChange += (key, value) => mapChanges.Add(key);

            Patch(room, J(Arena), "[{\"op\":\"set\",\"path\":[\"avatars\",\"p1\",\"pos\"],\"value\":[9.0,2.0]}]");
            Assert.AreEqual(1, posChanges);
            CollectionAssert.AreEqual(new[] { "p1" }, mapChanges);
            Assert.AreSame(held, room.State.Avatars["p1"]);
            Assert.AreEqual(9f, held.Pos[0]);
        }

        [Test]
        public void Del_RaisesOnRemove()
        {
            var room = new HearthRoom<ArenaRoomArena>();
            room.ApplyReset(J(Arena));
            var removed = new List<string>();
            room.State.Avatars.OnRemove += removed.Add;
            Patch(room, J(Arena), "[{\"op\":\"del\",\"path\":[\"avatars\",\"p1\"]}]");
            CollectionAssert.AreEqual(new[] { "p1" }, removed);
            Assert.IsFalse(room.State.Avatars.ContainsKey("p1"));
        }

        const string Board = "{\"cells\":[0,0,0,0,0,0,0,0,0],\"marks\":{\"x\":1,\"o\":2},\"turn\":\"x\",\"status\":\"Playing\"}";

        [Test]
        public void Splice_RaisesListOnChange()
        {
            var room = new HearthRoom<TicTacToeBoard>();
            room.ApplyReset(J(Board));
            var changes = 0;
            room.State.Cells.OnChange += () => changes++;
            Patch(room, J(Board), "[{\"op\":\"list_splice\",\"path\":[\"cells\"],\"index\":0,\"delete\":1,\"insert\":[1]}]");
            Assert.AreEqual(1, changes);
            Assert.AreEqual(1, room.State.Cells[0]);
        }

        [Test]
        public void EnumSet_RaisesFieldEvent_WithVariant()
        {
            var room = new HearthRoom<TicTacToeBoard>();
            room.ApplyReset(J(Board));
            TicTacToeStatus seen = null;
            room.State.OnStatusChange += status => seen = status;
            Patch(room, J(Board), "[{\"op\":\"set\",\"path\":[\"status\"],\"value\":{\"Won\":\"x\"}}]");
            Assert.AreEqual(TicTacToeStatus.Won, seen.Variant);
            Assert.AreEqual("x", seen.AsWon);
            Assert.AreSame(seen, room.State.Status);
        }

        [Test]
        public void IdenticalReload_RaisesNothing()
        {
            var room = new HearthRoom<TicTacToeBoard>();
            room.ApplyReset(J(Board));
            var events = 0;
            room.State.Cells.OnChange += () => events++;
            room.State.Marks.OnAdd += (k, v) => events++;
            room.State.Marks.OnChange += (k, v) => events++;
            room.State.Marks.OnRemove += k => events++;
            room.State.OnTurnChange += t => events++;
            room.State.OnStatusChange += s => events++;
            room.ApplyReset(J(Board));
            Assert.AreEqual(0, events);
        }

        [Test]
        public void Reset_RaisesOnlyWhatDiffers()
        {
            var room = new HearthRoom<TicTacToeBoard>();
            room.ApplyReset(J(Board));
            var log = new List<string>();
            room.State.Cells.OnChange += () => log.Add("cells");
            room.State.Marks.OnChange += (k, v) => log.Add("marks:" + k);
            room.State.OnTurnChange += t => log.Add("turn:" + t);
            room.State.OnStatusChange += s => log.Add("status");
            room.ApplyReset(J(Board.Replace("\"turn\":\"x\"", "\"turn\":\"o\"")));
            CollectionAssert.AreEqual(new[] { "turn:o" }, log);
        }

        [Test]
        public void JoinAsyncT_UsesSchemaAttribute()
        {
            var logic = new ClientLogicTests();
            logic.SetUp();
            try
            {
                _ = logic.client.JoinAsync<TicTacToeBoard>("tictactoe", "r1");
                logic.Socket.Push(TransportEvent.Opened());
                logic.client.Tick();
                var hello = JObject.Parse(Encoding.UTF8.GetString(logic.Socket.Sent[0].data));
                Assert.AreEqual(TicTacToeBoard.SchemaHash, (string)hello["schema_hash"]);

                logic.Socket.Server("{\"op\":\"JOIN_OK\",\"player_id\":\"x\",\"seat\":0}");
                logic.Socket.Server("{\"op\":\"FULL_STATE\",\"seq\":1,\"state\":" + Board + "}");
                logic.client.Tick();
                var room = (HearthRoom<TicTacToeBoard>)logic.client.Room;
                Assert.AreEqual("x", room.State.Turn);
                Assert.AreEqual(TicTacToeStatus.Playing, room.State.Status.Variant);
            }
            finally
            {
                logic.TearDown();
            }
        }

        [Test]
        public void Intents_AreExternallyTagged()
        {
            Assert.IsTrue(JToken.DeepEquals(J("{\"Place\":{\"cell\":4}}"), TicTacToeIntents.Place(4)));
            Assert.IsTrue(JToken.DeepEquals(J("\"Rematch\""), TicTacToeIntents.Rematch()));
        }
    }
}
